package com.bank.flink.sql;

import java.math.BigDecimal;

// A streaming transaction row.
class Txn {
    private final String txnId;
    private final String branch;
    private final BigDecimal amount;

    Txn(String txnId, String branch, BigDecimal amount) {
        this.txnId = txnId;
        this.branch = branch;
        this.amount = amount;
    }

    String getTxnId() { return txnId; }
    String getBranch() { return branch; }
    BigDecimal getAmount() { return amount; }
}
