package com.bank.flink.sql;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Represents the evolving 'transactions' dynamic table: rows arrive over time.
class DynamicTable {
    private static final Logger log = Logger.getLogger(DynamicTable.class.getName());
    private final List<Txn> rows = new ArrayList<>();

    void append(Txn t) {
        rows.add(t);
        log.fine(() -> "dynamic table gained row " + t.getTxnId());
    }

    List<Txn> rows() { return rows; }
}
