package com.bank.flink.sql;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Models a continuous GROUP BY branch SUM(amount) query that emits an
// UPSERT changelog (one upsert row per affected branch, keyed by branch).
class ContinuousQuery {
    private static final Logger log = Logger.getLogger(ContinuousQuery.class.getName());

    // Maintained result (the result dynamic table), keyed by branch.
    private final Map<String, BigDecimal> branchTotals = new LinkedHashMap<>();

    // Process one input row; emit the upsert for the affected branch.
    String onRow(Txn t) {
        BigDecimal newTotal = branchTotals.merge(t.getBranch(), t.getAmount(), BigDecimal::add);
        String upsert = "UPSERT branch=" + t.getBranch() + " total=" + newTotal;
        log.info(() -> upsert);
        return upsert;
    }

    Map<String, BigDecimal> materialized() { return branchTotals; }
}
