package com.bank.flink.sql;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FlinkSqlDemo {
    private static final Logger log = Logger.getLogger(FlinkSqlDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        DynamicTable transactions = new DynamicTable();
        ContinuousQuery query = new ContinuousQuery();

        // Transactions arrive continuously; the query updates results each time.
        Txn[] feed = {
            new Txn("T1", "MUMBAI", new BigDecimal("50000")),
            new Txn("T2", "DELHI",  new BigDecimal("12000")),
            new Txn("T3", "MUMBAI", new BigDecimal("30000")),  // updates MUMBAI
            new Txn("T4", "DELHI",  new BigDecimal("8000")),   // updates DELHI
            new Txn("T5", "MUMBAI", new BigDecimal("20000"))   // updates MUMBAI again
        };
        for (Txn t : feed) {
            transactions.append(t);     // dynamic table grows
            query.onRow(t);             // continuous query emits an upsert
        }

        log.info("materialized branch_totals = " + query.materialized());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
